<?php
declare(strict_types=1);
require __DIR__.'/private/layout.php';
$s=settings();
$page=(string)($_GET['page']??'home');
$allowed=['home','about','start','servers','news','article','shop','community','faq','rules','support','privacy','terms'];
if(!in_array($page,$allowed,true)){$page='404';http_response_code(404);}
if($page==='support' && $_SERVER['REQUEST_METHOD']==='POST') {
    csrf_check();
    if (!empty($_POST['website'])) {redirect(page_url('support'));}
    $recent=(int)($_SESSION['ticket_time']??0);
    if(time()-$recent < 60){set_flash('error','Следующее обращение можно отправить через минуту.');redirect(page_url('support'));}
    $name=trimmed('name',80);$contact=trimmed('contact',160);$subject=trimmed('subject',140);$message=trimmed('message',5000);
    if(strlen($name)<2 || strlen($contact)<3 || strlen($subject)<3 || strlen($message)<20) {
        set_flash('error','Заполните все поля. Сообщение должно содержать не менее 20 символов.');redirect(page_url('support'));
    }
    if (strlen($message)>5000 || strlen($contact)>250) {set_flash('error','Обращение слишком длинное.');redirect(page_url('support'));}
    $ticket=['id'=>strtoupper(substr(slug_id(),0,10)),'created'=>date('c'),'name'=>$name,'contact'=>$contact,'subject'=>$subject,'message'=>$message,'status'=>'new'];
    store_mutate('tickets',static function($all)use($ticket){if(!is_array($all))$all=[];array_unshift($all,$ticket);return array_slice($all,0,1000);});
    $_SESSION['ticket_time']=time();
    set_flash('success','Обращение №'.$ticket['id'].' отправлено. Команда сможет прочитать его в панели управления.');
    redirect(page_url('support'));
}
$headings=['home'=>'Главная','about'=>'О проекте','start'=>'Начать играть','servers'=>'Серверы','news'=>'Новости','article'=>'Публикация','shop'=>'Магазин','community'=>'Сообщество','faq'=>'Вопросы и ответы','rules'=>'Правила проекта','support'=>'Поддержка','privacy'=>'Конфиденциальность','terms'=>'Условия использования','404'=>'Страница не найдена'];
$allNews=array_values(array_filter(store_read('news',[]),static fn($v)=>!empty($v['published'])));
usort($allNews,static fn($a,$b)=>strcmp((string)($b['date']??''),(string)($a['date']??'')));
$servers=store_read('servers',[]);$products=store_read('products',[]);$faqs=store_read('faqs',[]);
$article=null;
if($page==='article') {foreach($allNews as $item)if(($item['id']??'')===($_GET['id']??'')){$article=$item;break;}if(!$article){$page='404';http_response_code(404);}}
render_head($page==='article'&&$article?$article['title']:($headings[$page]??'Страница'),$page);
